/**
 * Drizzle schema for the Undangan Digital Cloudflare D1 database.
 *
 * Conventions:
 * - IDs are `text` primary keys generated by the application (UUIDs), never by
 *   the database.
 * - Money is an `integer` amount of rupiah, with no cents.
 * - Timestamps are `integer` Unix seconds (`{ mode: 'timestamp' }`), defaulted
 *   with `unixepoch()`; `updated_at` also refreshes through `$onUpdate`.
 * - `*Json` columns are plain `text` with SQL string defaults. They are parsed
 *   and validated at API boundaries, not by the ORM.
 * - Every enum column carries both a TypeScript union (from the `enum` option)
 *   and a DB-level CHECK constraint. Both derive from the tuples exported by
 *   `@kalamkala/contracts`, so writers outside Drizzle cannot store values the
 *   application does not understand.
 */

import { sql } from 'drizzle-orm'
import {
  check,
  index,
  integer,
  sqliteTable,
  text,
  uniqueIndex,
} from 'drizzle-orm/sqlite-core'

import {
  DISCOUNT_TYPES,
  GUEST_CATEGORIES,
  INVITATION_REPORT_REASONS,
  INVITATION_STATUSES,
  INVITATION_TIERS,
  PAYMENT_PROVIDERS,
  RSVP_ATTENDANCES,
  TRANSACTION_STATUSES,
  USER_ROLES,
  WA_SENT_STATUSES,
} from '@kalamkala/contracts'

/**
 * Renders a domain enum tuple as a SQL literal list for CHECK constraints.
 * Values are compile-time constants, but quotes are escaped anyway so adding a
 * value with an apostrophe later cannot break the generated migration.
 */
const sqlLiteralList = (values: readonly string[]): string =>
  values.map((value) => `'${value.replace(/'/g, "''")}'`).join(', ')

const createdAtColumn = () =>
  integer('created_at', { mode: 'timestamp' })
    .notNull()
    .default(sql`(unixepoch())`)

const updatedAtColumn = () =>
  integer('updated_at', { mode: 'timestamp' })
    .notNull()
    .default(sql`(unixepoch())`)
    .$onUpdate(() => new Date())

/** Better Auth core user table, plus application fields. */
export const users = sqliteTable(
  'users',
  {
    id: text('id').primaryKey(),
    name: text('name').notNull(),
    email: text('email').notNull().unique(),
    emailVerified: integer('email_verified', { mode: 'boolean' })
      .notNull()
      .default(false),
    image: text('image'),
    createdAt: createdAtColumn(),
    updatedAt: updatedAtColumn(),
    role: text('role', { enum: USER_ROLES }).notNull().default('USER'),
    whatsappNumber: text('whatsapp_number'),
  },
  (table) => [
    check(
      'users_role_check',
      sql`${table.role} in (${sql.raw(sqlLiteralList(USER_ROLES))})`,
    ),
  ],
)

/** Better Auth session table. */
export const sessions = sqliteTable(
  'sessions',
  {
    id: text('id').primaryKey(),
    expiresAt: integer('expires_at', { mode: 'timestamp' }).notNull(),
    token: text('token').notNull().unique(),
    createdAt: createdAtColumn(),
    updatedAt: updatedAtColumn(),
    ipAddress: text('ip_address'),
    userAgent: text('user_agent'),
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
  },
  (table) => [index('sessions_user_id_idx').on(table.userId)],
)

/** Better Auth account table (OAuth providers and credential passwords). */
export const accounts = sqliteTable(
  'accounts',
  {
    id: text('id').primaryKey(),
    accountId: text('account_id').notNull(),
    providerId: text('provider_id').notNull(),
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    accessToken: text('access_token'),
    refreshToken: text('refresh_token'),
    idToken: text('id_token'),
    accessTokenExpiresAt: integer('access_token_expires_at', {
      mode: 'timestamp',
    }),
    refreshTokenExpiresAt: integer('refresh_token_expires_at', {
      mode: 'timestamp',
    }),
    scope: text('scope'),
    password: text('password'),
    createdAt: createdAtColumn(),
    updatedAt: updatedAtColumn(),
  },
  (table) => [
    uniqueIndex('accounts_provider_id_account_id_unique').on(
      table.providerId,
      table.accountId,
    ),
    index('accounts_user_id_idx').on(table.userId),
  ],
)

/** Better Auth verification table (magic links, password resets). */
export const verifications = sqliteTable(
  'verifications',
  {
    id: text('id').primaryKey(),
    identifier: text('identifier').notNull(),
    value: text('value').notNull(),
    expiresAt: integer('expires_at', { mode: 'timestamp' }).notNull(),
    createdAt: createdAtColumn(),
    updatedAt: updatedAtColumn(),
  },
  (table) => [index('verifications_identifier_idx').on(table.identifier)],
)

/** Template catalog. IDs are stable slugs such as `klasik-emas`. */
export const catalogTemplates = sqliteTable(
  'catalog_templates',
  {
    id: text('id').primaryKey(),
    name: text('name').notNull(),
    tier: text('tier', { enum: INVITATION_TIERS }).notNull(),
    isVisible: integer('is_visible', { mode: 'boolean' })
      .notNull()
      .default(true),
    sortOrder: integer('sort_order').notNull().default(0),
    createdAt: createdAtColumn(),
    updatedAt: updatedAtColumn(),
  },
  (table) => [
    check(
      'catalog_templates_tier_check',
      sql`${table.tier} in (${sql.raw(sqlLiteralList(INVITATION_TIERS))})`,
    ),
  ],
)

/** An owner's invitation site built from a catalog template. */
export const invitations = sqliteTable(
  'invitations',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    slug: text('slug').notNull().unique(),
    templateId: text('template_id')
      .notNull()
      .references(() => catalogTemplates.id),
    tier: text('tier', { enum: INVITATION_TIERS }).notNull(),
    status: text('status', { enum: INVITATION_STATUSES })
      .notNull()
      .default('DRAFT'),
    contentJson: text('content_json').notNull().default('{}'),
    appearanceJson: text('appearance_json'),
    publishedAt: integer('published_at', { mode: 'timestamp' }),
    expiresAt: integer('expires_at', { mode: 'timestamp' }),
    createdAt: createdAtColumn(),
    updatedAt: updatedAtColumn(),
  },
  (table) => [
    index('invitations_user_id_idx').on(table.userId),
    index('invitations_template_id_idx').on(table.templateId),
    check(
      'invitations_tier_check',
      sql`${table.tier} in (${sql.raw(sqlLiteralList(INVITATION_TIERS))})`,
    ),
    check(
      'invitations_status_check',
      sql`${table.status} in (${sql.raw(sqlLiteralList(INVITATION_STATUSES))})`,
    ),
  ],
)

/** Abuse reports for admin triage. Reporter identity is a hash, never an IP. */
export const invitationReports = sqliteTable(
  'invitation_reports',
  {
    id: text('id').primaryKey(),
    invitationId: text('invitation_id')
      .notNull()
      .references(() => invitations.id, { onDelete: 'cascade' }),
    reason: text('reason', { enum: INVITATION_REPORT_REASONS }).notNull(),
    note: text('note'),
    reporterHash: text('reporter_hash'),
    createdAt: createdAtColumn(),
  },
  (table) => [
    index('invitation_reports_invitation_id_idx').on(table.invitationId),
    check(
      'invitation_reports_reason_check',
      sql`${table.reason} in (${sql.raw(sqlLiteralList(INVITATION_REPORT_REASONS))})`,
    ),
  ],
)

/** A guest list entry; `qrToken` backs the personal check-in code. */
export const guests = sqliteTable(
  'guests',
  {
    id: text('id').primaryKey(),
    invitationId: text('invitation_id')
      .notNull()
      .references(() => invitations.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    phoneNormalized: text('phone_normalized'),
    category: text('category', { enum: GUEST_CATEGORIES })
      .notNull()
      .default('REGULER'),
    allowedEventIdsJson: text('allowed_event_ids_json').notNull().default('[]'),
    maxPax: integer('max_pax').notNull().default(1),
    tableNumber: text('table_number'),
    sessionLabel: text('session_label'),
    qrToken: text('qr_token').notNull().unique(),
    waSentStatus: text('wa_sent_status', { enum: WA_SENT_STATUSES })
      .notNull()
      .default('PENDING'),
    waSentAt: integer('wa_sent_at', { mode: 'timestamp' }),
    createdAt: createdAtColumn(),
    updatedAt: updatedAtColumn(),
  },
  (table) => [
    index('guests_invitation_id_idx').on(table.invitationId),
    check(
      'guests_category_check',
      sql`${table.category} in (${sql.raw(sqlLiteralList(GUEST_CATEGORIES))})`,
    ),
    check(
      'guests_wa_sent_status_check',
      sql`${table.waSentStatus} in (${sql.raw(sqlLiteralList(WA_SENT_STATUSES))})`,
    ),
  ],
)

/** RSVP messages. A guest row may be deleted while the message is kept. */
export const rsvps = sqliteTable(
  'rsvps',
  {
    id: text('id').primaryKey(),
    invitationId: text('invitation_id')
      .notNull()
      .references(() => invitations.id, { onDelete: 'cascade' }),
    guestId: text('guest_id').references(() => guests.id, {
      onDelete: 'set null',
    }),
    guestName: text('guest_name').notNull(),
    attendance: text('attendance', { enum: RSVP_ATTENDANCES }).notNull(),
    guestCount: integer('guest_count').notNull().default(1),
    message: text('message'),
    hostReply: text('host_reply'),
    isHidden: integer('is_hidden', { mode: 'boolean' }).notNull().default(false),
    createdAt: createdAtColumn(),
  },
  (table) => [
    index('rsvps_invitation_id_idx').on(table.invitationId),
    index('rsvps_guest_id_idx').on(table.guestId),
    check(
      'rsvps_attendance_check',
      sql`${table.attendance} in (${sql.raw(sqlLiteralList(RSVP_ATTENDANCES))})`,
    ),
  ],
)

/** Payment attempts. `merchantOrderId` is the idempotency key per gateway. */
export const transactions = sqliteTable(
  'transactions',
  {
    id: text('id').primaryKey(),
    invitationId: text('invitation_id')
      .notNull()
      .references(() => invitations.id, { onDelete: 'cascade' }),
    userId: text('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    merchantOrderId: text('merchant_order_id').notNull().unique(),
    gatewayProvider: text('gateway_provider', { enum: PAYMENT_PROVIDERS })
      .notNull()
      .default('SIMULATED'),
    gatewayReference: text('gateway_reference'),
    // No FK on purpose: promo codes are free-text applied at checkout and must
    // stay readable after a promo row is deleted.
    promoCode: text('promo_code'),
    amount: integer('amount').notNull(),
    status: text('status', { enum: TRANSACTION_STATUSES })
      .notNull()
      .default('PENDING'),
    paidAt: integer('paid_at', { mode: 'timestamp' }),
    createdAt: createdAtColumn(),
    updatedAt: updatedAtColumn(),
  },
  (table) => [
    index('transactions_invitation_id_idx').on(table.invitationId),
    index('transactions_user_id_idx').on(table.userId),
    index('transactions_status_idx').on(table.status),
    check(
      'transactions_gateway_provider_check',
      sql`${table.gatewayProvider} in (${sql.raw(sqlLiteralList(PAYMENT_PROVIDERS))})`,
    ),
    check(
      'transactions_status_check',
      sql`${table.status} in (${sql.raw(sqlLiteralList(TRANSACTION_STATUSES))})`,
    ),
  ],
)

/** Discount codes, including partner commissions. */
export const promos = sqliteTable(
  'promos',
  {
    id: text('id').primaryKey(),
    code: text('code').notNull().unique(),
    discountType: text('discount_type', { enum: DISCOUNT_TYPES }).notNull(),
    discountValue: integer('discount_value').notNull(),
    partnerName: text('partner_name'),
    commissionPercent: integer('commission_percent'),
    maxUses: integer('max_uses'),
    usedCount: integer('used_count').notNull().default(0),
    isActive: integer('is_active', { mode: 'boolean' }).notNull().default(true),
    expiresAt: integer('expires_at', { mode: 'timestamp' }),
    createdAt: createdAtColumn(),
    updatedAt: updatedAtColumn(),
  },
  (table) => [
    check(
      'promos_discount_type_check',
      sql`${table.discountType} in (${sql.raw(sqlLiteralList(DISCOUNT_TYPES))})`,
    ),
  ],
)

/** Scoped access for co-hosts, planners, and family helpers. */
export const collaborators = sqliteTable(
  'collaborators',
  {
    id: text('id').primaryKey(),
    invitationId: text('invitation_id')
      .notNull()
      .references(() => invitations.id, { onDelete: 'cascade' }),
    label: text('label').notNull(),
    accessToken: text('access_token').notNull().unique(),
    pinHash: text('pin_hash'),
    permissionsJson: text('permissions_json').notNull().default('{}'),
    expiresAt: integer('expires_at', { mode: 'timestamp' }),
    createdAt: createdAtColumn(),
    updatedAt: updatedAtColumn(),
  },
  (table) => [index('collaborators_invitation_id_idx').on(table.invitationId)],
)

/**
 * All tables as one const object. Adapters use it to type a Drizzle client as
 * `DrizzleD1Database<typeof schema>`.
 */
export const schema = {
  users,
  sessions,
  accounts,
  verifications,
  catalogTemplates,
  invitations,
  invitationReports,
  guests,
  rsvps,
  transactions,
  promos,
  collaborators,
} as const
